    # Compute possible exponent by repeated multiplication or using logarithms.
    # Since we need integer exponent, we can loop multiplying until we exceed x or match.
    current = 1
    exp = 0
    while current <= x:
        if current == x:
            return True
        current *= n
        exp += 1
    return False

