def solve(s):
    # Check if there are any letters in the string
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # If no letters, reverse the entire string
        return s[::-1]
    else:
        # Reverse case of each letter and keep non-letters as is
        result = []
        for char in s:
            if char.isalpha():
                # Toggle case: lower to upper or upper to lower
                result.append(char.swapcase())
            else:
                result.append(char)
        return ''.join(result)

